<script lang="ts">export interface TabItem{label:string;value:string;content:string;disabled?:boolean}let{items,value=$bindable('')}:{items:TabItem[];value?:string}=$props();$effect(()=>{if(!items.some(x=>x.value===value&&!x.disabled))value=items.find(x=>!x.disabled)?.value||'';});</script>
<div class="ds-tabs"><div class="tablist" role="tablist">{#each items as item}<button class="ds-focus" role="tab" aria-selected={value===item.value} tabindex={value===item.value?0:-1} disabled={item.disabled} onclick={()=>value=item.value}>{item.label}</button>{/each}</div>{#each items.filter(x=>x.value===value) as item}<div class="panel" role="tabpanel" tabindex="0">{item.content}</div>{/each}</div>
<style>.tablist{display:flex;gap:.25rem;border-bottom:1px solid var(--ds-border);overflow-x:auto}.tablist button{padding:.75rem 1rem;border:0;background:transparent;color:var(--ds-muted);font:600 .8125rem var(--ds-font);white-space:nowrap;cursor:pointer}.tablist button[aria-selected=true]{color:var(--ds-text);border-bottom:2px solid var(--ds-primary)}.tablist button:disabled{opacity:.4}.panel{padding:1rem 0;color:var(--ds-text);font-size:.875rem}</style>